import time
import subprocess
import os

# Create a truly silent 1-second WAV file using standard Linux tools (sox/play)
# if needed, or simply use mpg123 with a generated silent mp3.
# Wait, a simple way on linux without generating files is using 'play' from sox:
# os.system('play -n synth 0.1 noisered') 
# We'll use a very short, completely silent burst generated by python if we don't have a file.

import wave
import struct

def create_silent_wav(filename="silence.wav"):
    # Generate 0.5 seconds of absolute 0 amplitude (silence)
    sample_rate = 44100
    duration = 0.5
    num_samples = int(sample_rate * duration)
    
    with wave.open(filename, 'w') as wav_file:
        wav_file.setnchannels(1)
        wav_file.setsampwidth(2)
        wav_file.setframerate(sample_rate)
        
        for _ in range(num_samples):
            data = struct.pack('<h', 0)
            wav_file.writeframesraw(data)
            
if __name__ == "__main__":
    print("[KEEPALIVE] Starting Bluetooth Silence Stream...")
    create_silent_wav("silence.wav")
    
    while True:
        try:
            # Play the silent audio every 5 minutes (300 seconds). 
            # Most bluetooth speakers sleep after 15 mins.
            subprocess.run(["aplay", "-q", "silence.wav"])
            time.sleep(300)
        except Exception as e:
            print(f"[KEEPALIVE] Error: {e}")
            time.sleep(60)
